import { Component, computed, inject, input, signal } from '@angular/core';
import { toObservable, toSignal } from '@angular/core/rxjs-interop';
import { Router } from '@angular/router';
import { catchError, EMPTY, map, startWith, switchMap } from 'rxjs';
import { CinemaApi } from '../cinema-api';
import { showDate } from '../dates';
import { Movie, Screening } from '../models';
import { Toaster } from '../toast/toaster';

export interface SeatCell {
  kind: 'seat';
  id: string;
  row: number;
  column: number;
  accessible: boolean;
}

export interface CouchCell {
  kind: 'couch';
  id: string;
  row: number;
  start: number;
  end: number;
  ids: string[];
}

export type Cell = SeatCell | CouchCell;

export interface AuditoriumRow {
  row: number;
  cells: Cell[];
}

export type SeatState = 'available' | 'selected' | 'unavailable' | 'accessible';

type LoadState =
  | { status: 'loading' }
  | { status: 'ready'; screening: Screening; movie: Movie };

const ROW_COUNT = 15;
const COLUMN_COUNT = 24;
const LAST_ROW = 15;
const MAX_SEATS = 10;

function seatId(row: number, column: number): string {
  return `R${row}C${column}`;
}

function buildAuditorium(): AuditoriumRow[] {
  return Array.from({ length: ROW_COUNT }, (_, index) => {
    const row = index + 1;
    if (row === LAST_ROW) {
      const cells: CouchCell[] = [];
      for (let start = 1; start < COLUMN_COUNT; start += 2) {
        const end = start + 1;
        cells.push({
          kind: 'couch',
          id: seatId(row, start),
          row,
          start,
          end,
          ids: [seatId(row, start), seatId(row, end)],
        });
      }
      return { row, cells };
    }
    const firstColumn = row <= 10 ? 5 : 1;
    const cells: SeatCell[] = [];
    for (let column = firstColumn; column <= COLUMN_COUNT; column++) {
      cells.push({
        kind: 'seat',
        id: seatId(row, column),
        row,
        column,
        accessible: row === 1 && column >= 10 && column <= 15,
      });
    }
    return { row, cells };
  });
}

function seatCount(cell: Cell): number {
  return cell.kind === 'couch' ? 2 : 1;
}

function firstColumn(cell: Cell): number {
  return cell.kind === 'couch' ? cell.start : cell.column;
}

function label(cell: Cell): string {
  return cell.kind === 'couch' ? `${cell.start}-${cell.end}` : String(cell.column);
}

@Component({
  selector: 'app-seat-selection',
  templateUrl: './seat-selection.html',
  styleUrl: './seat-selection.scss',
})
export class SeatSelection {
  private readonly api = inject(CinemaApi);
  private readonly router = inject(Router);
  private readonly toaster = inject(Toaster);

  readonly id = input.required<string>();

  protected readonly rows = buildAuditorium();

  protected readonly legend: { state: SeatState; name: string }[] = [
    { state: 'available', name: 'Available' },
    { state: 'selected', name: 'Selected' },
    { state: 'unavailable', name: 'Unavailable' },
    { state: 'accessible', name: 'Accessible' },
  ];

  protected readonly state = toSignal(
    toObservable(this.id).pipe(
      switchMap((id) =>
        this.api.getScreening(Number(id)).pipe(
          switchMap((screening) =>
            this.api.getMovie(screening.movieId).pipe(
              map((movie): LoadState => ({ status: 'ready', screening, movie })),
            ),
          ),
          startWith<LoadState>({ status: 'loading' }),
          catchError(() => {
            void this.router.navigateByUrl('/');
            return EMPTY;
          }),
        ),
      ),
    ),
    { initialValue: { status: 'loading' } as LoadState },
