    const couch = allCells.find((cell) => cell.kind === 'couch')!;
    expect(priceOf(couch)).toBe(89);
  });

  it('formats prices with two decimals and the currency', () => {
    expect(formatPrice(121)).toBe('121.00 PLN');
  });
});

